export class ExperimentalServerTasks{constructor(s){this._server=s}requestStream(s,e,r){return this._server.requestStream(s,e,r)}async getTask(s,e){return this._server.getTask({taskId:s},e)}async getTaskResult(s,e,r){return this._server.getTaskResult({taskId:s},e,r)}async listTasks(s,e){return this._server.listTasks(s?{cursor:s}:void 0,e)}async cancelTask(s,e){return this._server.cancelTask({taskId:s},e)}}